package `in`.samtravels.app

import org.json.JSONObject
import java.time.Instant
import java.util.UUID

/** Durable completed-ride financial obligation and Room-backed v1 working copy. */
object DriverTripFinancialStore {
 private fun obligationId(tripId:String)="work:trip-financial-obligation:$tripId"
 private fun draftId(tripId:String)="__sam_travels_form_working_copy__:work.trip-completed-financials:$tripId"
 fun createPendingObligation(db:LocalDatabase,tripId:String,eventId:String,now:String,tripContext:JSONObject?) {
  require(tripId.matches(Regex("[A-Za-z0-9_-]{1,128}"))) { "completed_trip_identity_missing" }
  val id=obligationId(tripId);require(db.records().get(id)==null) { "trip_financial_obligation_already_exists" }
  val data=JSONObject().put("schemaVersion",1).put("tripId",tripId).put("kind","completed_ride_financials").put("status","pending").put("endRideEventId",eventId).put("createdAt",now)
  tripContext?.let { data.put("tripContext",JSONObject(it.toString())) }
  val envelope=JSONObject().put("id",id).put("schemaVersion",1).put("createdAt",now).put("updatedAt",now).put("source","android").put("revision",1).put("data",data)
  db.records().put(StoredRecord(id,envelope.toString(),1,now))
 }
 fun pendingObligations(db:LocalDatabase):List<JSONObject> = db.records().list().filter { row -> row.id.startsWith("work:trip-financial-obligation:") && JSONObject(row.json).optJSONObject("data")?.let { it.optString("kind")=="completed_ride_financials"&&it.optString("status")=="pending" }==true }.map { JSONObject(it.json) }
 fun ensureDraft(db:LocalDatabase,tripId:String):JSONObject {
  require(tripId.matches(Regex("[A-Za-z0-9_-]{1,128}"))) { "trip_id_invalid" };var result:JSONObject?=null
  db.runInTransaction { val id=draftId(tripId);val existing=db.records().get(id)
   if(existing!=null){val copy=JSONObject(existing.json).optJSONObject("data")?:error("form_working_copy_invalid");require(copy.optString("formId")=="work.trip-completed-financials"&&copy.optInt("formVersion",-1)==1&&copy.optString("instanceId")==tripId&&copy.optString("status") in setOf("in_progress","submitted")){"form_working_copy_invalid"};result=copy}
   else {val now=Instant.now().toString();val copy=JSONObject().put("formId","work.trip-completed-financials").put("formVersion",1).put("instanceId",tripId).put("revision",0).put("status","in_progress").put("values",JSONObject().put("tripId",tripId)).put("operationId",UUID.randomUUID().toString()).put("updatedAt",now);val envelope=JSONObject().put("id",id).put("schemaVersion",1).put("createdAt",now).put("updatedAt",now).put("source","android").put("revision",1).put("data",copy);db.records().put(StoredRecord(id,envelope.toString(),1,now));result=copy}
  };return result?:error("form_working_copy_unavailable")
 }
 fun updateDraft(db:LocalDatabase,tripId:String,values:JSONObject) { validate(values,tripId,true);db.runInTransaction { val id=draftId(tripId);val row=db.records().get(id)?:error("form_working_copy_missing");val envelope=JSONObject(row.json);val copy=envelope.optJSONObject("data")?:error("form_working_copy_invalid");require(copy.optString("formId")=="work.trip-completed-financials"&&copy.optString("instanceId")==tripId&&copy.optString("status")=="in_progress"){"form_working_copy_invalid"};val now=Instant.now().toString();copy.put("revision",copy.optInt("revision")+1).put("values",JSONObject(values.toString()).put("tripId",tripId)).put("updatedAt",now);envelope.put("revision",envelope.optInt("revision")+1).put("updatedAt",now).put("data",copy);db.records().put(StoredRecord(id,envelope.toString(),row.schemaVersion,now))} }
 fun submit(db:LocalDatabase,tripId:String,values:JSONObject):JSONObject { validate(values,tripId,false);ensureDraft(db,tripId);var result:JSONObject?=null;db.runInTransaction { val id=obligationId(tripId);val row=db.records().get(id)?:error("completed_trip_financial_obligation_missing");val envelope=JSONObject(row.json);val data=envelope.optJSONObject("data")?:error("completed_trip_financial_obligation_invalid");require(data.optString("kind")=="completed_ride_financials"&&data.optString("tripId")==tripId){"completed_trip_financial_obligation_invalid"};val copyRow=db.records().get(draftId(tripId))?:error("form_working_copy_missing");val copyEnvelope=JSONObject(copyRow.json);val copy=copyEnvelope.optJSONObject("data")?:error("form_working_copy_invalid");val copyValues=copy.optJSONObject("values")?:error("form_working_copy_invalid");val op=copy.optString("operationId");if(data.optString("status")=="submitted"){require(data.optString("operationId")==op&&sameValues(data,values)){"completed_trip_financials_already_submitted"};result=envelope;return@runInTransaction};require(data.optString("status")=="pending"){"completed_trip_financial_obligation_invalid"};require(sameValues(copyValues,values)){"completed_trip_financial_draft_mismatch"};val now=Instant.now().toString();listOf("farePaise","tollPaise","tollPayer","parkingPaise","parkingPayer").forEach { key -> if(values.has(key))data.put(key,values.get(key)) else data.remove(key) };data.put("status","submitted").put("operationId",op).put("submittedAt",now);envelope.put("revision",envelope.optInt("revision")+1).put("updatedAt",now).put("data",data);copy.put("status","submitted").put("revision",copy.optInt("revision")+1).put("updatedAt",now);copyEnvelope.put("revision",copyEnvelope.optInt("revision")+1).put("updatedAt",now).put("data",copy);db.records().put(StoredRecord(id,envelope.toString(),row.schemaVersion,now));db.records().put(StoredRecord(draftId(tripId),copyEnvelope.toString(),copyRow.schemaVersion,now));result=envelope };return result?:error("completed_trip_financials_not_submitted") }
 private fun sameValues(left:JSONObject,right:JSONObject)=listOf("farePaise","tollPaise","tollPayer","parkingPaise","parkingPayer").all { key -> if(left.has(key)!=right.has(key))false else !left.has(key)||left.opt(key).toString()==right.opt(key).toString() }
 private fun validate(values:JSONObject,tripId:String,allowMissingFare:Boolean) { require(tripId.matches(Regex("[A-Za-z0-9_-]{1,128}"))){"trip_id_invalid"};if(!allowMissingFare)require(values.has("farePaise")){"fare_required_non_negative_integer_paise"};if(values.has("farePaise"))require(values.optLong("farePaise",-1L)>=0L&&values.optDouble("farePaise",Double.NaN)%1.0==0.0){"fare_required_non_negative_integer_paise"};listOf("toll","parking").forEach { kind -> val a=kind+"Paise";val p=kind+"Payer";if(values.has(a)){require(values.optLong(a,-1L)>=0L&&values.optDouble(a,Double.NaN)%1.0==0.0){kind+"_must_be_non_negative_integer_paise"};require(values.optString(p) in setOf("driver","customer")){kind+"_payer_required"}}else require(!values.has(p)){kind+"_payer_without_amount"} } }
}
